const order = {
  lines: [],
  add(name) {
    this.lines.push(name);

    return this;
  },
  count() {
    return this.lines.length;
  },
};

console.log(order.add("tea").count());
console.log(order.add("cake").add("jam").count());

try {
  order.count().add("milk");
} catch (error) {
  console.log(error.name);
}
